  /* ===================================================================
     1. CONFIG
     =================================================================== */
  var CONFIG = {
    title:   "BLIGHT",
    /* One sentence, and nothing else: the demo caption is dropped in the SKIN
       because the stage below already plays the drag / release / match beat. */
    tagline: "Drag to <b class=\"w-aim\">aim</b>, <b class=\"w-fire\">release</b> to shoot and match 3 bubbles",
    gameSeconds: 60,
    storeUrl: {
      ios:     "https://newrare-website.vercel.app/#playables",
      android: "https://newrare-website.vercel.app/#playables",
      fallback:"https://newrare-website.vercel.app/#playables"
    },
    designWidth: 720, designHeight: 1280, bg: "#0a0e24",
    // The grid hangs from Layout.top and the launcher sits above the CTA bar,
    // so nothing important ever ends up under the HUD or a notch.
    layout: { hudHeight: 150, ctaHeight: 118, sideMargin: 0 },
    intro: { logo: "logo", demo: "aim", caption: "" },
    hud: { score: true, timer: true },
    music: { volume: 0.10, fade: 2.0 },
    copy: {
      start:"TAP TO PLAY", ctaBar:"INSTALL NOW", ctaEnd:"PLAY THE FULL GAME",
      replay:"Replay the demo", scoreLabel:"SCORE", timeLabel:"TIME",
      endScore:"FINAL SCORE", gameOver:"OVERRUN!", timeUp:"TIME'S UP!"
    },

    /* --- game tunables --- */
    bubbleR: 30,                   // radius (diameter 60 => 12 columns fit 720)
    cols: 12,                      // bubbles on a non-offset row (offset rows hold cols-1)
    startRows: 6,                  // rows present at the start
    launcherOffset: 60,            // launcher this far above Layout.bottom
    dangerOffset: 150,             // a bubble reaching this line loses the round
    maxAimDeg: 82,                 // clamp the aim so you cannot shoot sideways
    shootSpeed: 1150,              // px/sec
    addRowShots: 5,                // push a fresh row down every N shots (pressure)
    blightInterval: 2,             // seconds between each blight spread
    wallSuperChance: 0.06,         // chance a wall bubble is a rainbow SUPER
    shotSuperChance: 0.12,         // chance the launcher hands you a SUPER

    // Only THREE base colours — easy matching, punchy reads.
    palette: [
      { light:"#ffd3dc", core:"#ff4d6d", edge:"#c11e46", glow:"rgba(255,77,109,.95)" },
      { light:"#fff1bd", core:"#ffc93c", edge:"#dc8a00", glow:"rgba(255,201,60,.95)" },
      { light:"#cfe6ff", core:"#3aa0ff", edge:"#1663d6", glow:"rgba(58,160,255,.95)" }
    ]
  };

  /* ===================================================================
     2. ASSETS
     =================================================================== */
  var ASSETS = {
    images: {
      logo: "data:image/jpeg;base64,",
      bg: "data:image/jpeg;base64,"
    },
    sounds: {
      // The background bed, looped and crossfaded by Music (see CONFIG.music):
      //   ffmpeg -i assets/sound/blight.mp3 -ac 1 -ar 44100 -b:a 64k music.mp3
      music: "data:audio/mpeg;base64,",
      // assets/sfx/*.mp3, trimmed and re-encoded mono 32 kHz / 64 kbps
      // shoot:  sfx_shoot_pool-v3                                (the launcher)
      // stick:  sfx_hitwall_sport_01                             (a shot that clears nothing)
      // pop:    pop_up_pop_002                                   (a cluster bursts, pitched by size)
      // blast:  alert_bright_warm_system_positive_002            (the super detonation)
      // drop:   alert_notification_clicks_fast_ascending_001     (the cascade of cut-off bubbles)
      // cheer:  alert_harp_positive_ascending_tone_musical       (5+ bubbles fall at once)
      // spread: pop_up_close_002                                 (the blight contaminates — a dull blip,
      //                                                          pitched down and kept quiet: it fires on
      //                                                          every blightInterval tick)
      // press:  ui_app_tone_delete_close_loud_001                (a fresh row is pushed in)
      shoot: "data:audio/mpeg;base64,",
      stick: "data:audio/mpeg;base64,",
      pop: "data:audio/mpeg;base64,",
      blast: "data:audio/mpeg;base64,",
      drop: "data:audio/mpeg;base64,",
      cheer: "data:audio/mpeg;base64,",
      spread: "data:audio/mpeg;base64,",
      press: "data:audio/mpeg;base64,",
      // End-screen cues, shared by every game (played through Sound.cue, so a
      // game that drops them falls back to the synthesized beeps).
      // uiScore: alert_ping_chime_correct_answer_check_positive_009
      // uiStar:  alert_mallet_chime_ring_notification_002  (pitched per star)
      // uiRow:   alert_menu_select_item_beep_click_003
      uiScore: "data:audio/mpeg;base64,",
      uiStar: "data:audio/mpeg;base64,",
      uiRow: "data:audio/mpeg;base64,"
    }
  };

  /* ===================================================================
     6. GAME — BLIGHT
     A classic hexagonal bubble shooter, tuned for a smooth frame rate:

       - A hex grid hangs from the top of Layout. Rows are staggered; a
         `rowShift` counter lets new rows be pushed in from the top while every
         existing bubble keeps its geometry (parity = (row + rowShift)).
         Only THREE base colours are used, so matching is instant to read.
       - SUPER bubbles: rare rainbow wildcards. Hitting one detonates EVERY
         other super on the board at once — a huge multicolour chain.
       - BLIGHT: one dark bubble spreads to a neighbour every few seconds. It
         never matches by colour; the only way out is to cut it off from the
         ceiling so it falls.
       - Drag to aim (dotted trajectory with one wall bounce), release to fire.
       - PERFORMANCE: every bubble and the background are pre-rendered once to
         a cached sprite and blitted with drawImage — no per-frame gradients or
         shadowBlur. All the juice goes through the engine's Fx layer.
     =================================================================== */
  var Game = (function () {
    var R = CONFIG.bubbleR, COLS = CONFIG.cols, PAL = CONFIG.palette;
    var ROWH = R * Math.sqrt(3);            // vertical spacing between hex rows
    var SPEED = CONFIG.shootSpeed;
    var MAX_AIM = CONFIG.maxAimDeg * Math.PI / 180;
    var ADD_SHOTS = CONFIG.addRowShots;
    var WALL_SUP = CONFIG.wallSuperChance, SHOT_SUP = CONFIG.shotSuperChance;
    var PI2 = Math.PI * 2;
    var COLLIDE = R * 2 * 0.9;              // centres this close => touching

    // --- geometry, derived from Layout so the grid never hides under the HUD
    // or the CTA bar and never sits behind a notch ---------------------------
    var GRID_TOP = 0, LX = 0, LY = 0, DANGER_Y = 0, ROWS = 22;

    // --- state -------------------------------------------------------------
    var grid;            // grid[r][c] = colour index or null
    var sup;             // sup[r][c]  = true if that bubble is a SUPER
    var blk;             // blk[r][c]  = true if that bubble is contaminated
    var wobble;          // wobble[r][c] = 0..1 impact tremor (decays)
    var rowShift;        // parity offset so pushed-in rows stay consistent
    var score, ball, nextColor, nextSuper;
    var aimAngle, aiming;
    var shotCount, maxCombo, streak, ended, blackTimer, totalCleared;
    var fallers, trail, bgT, fieldY, launchPunch;

    // --- cached sprites (built once — the core perf win) -------------------
    var bubbleSprites = null, superSprite = null, blackSprite = null, bgCanvas = null;

    function geometry() {
      GRID_TOP = Layout.top;
      LX = view.w / 2;
      LY = Layout.bottom - CONFIG.launcherOffset;
      DANGER_Y = Layout.bottom - CONFIG.dangerOffset;
    }
    function onResize() { geometry(); bgCanvas = null; buildBackground(); }

    // --- hex geometry ------------------------------------------------------
    function isOffset(r) { return (((r + rowShift) % 2) + 2) % 2 === 1; }
    function rowCols(r)  { return isOffset(r) ? COLS - 1 : COLS; }
    function cellX(r, c) { return R + c * 2 * R + (isOffset(r) ? R : 0); }
    function cellY(r)    { return GRID_TOP + r * ROWH + R; }
    function validCell(r, c) { return r >= 0 && r < ROWS && c >= 0 && c < rowCols(r); }
    function key(r, c) { return r + "_" + c; }

    function neighbors(r, c) {
      if (isOffset(r)) return [[r, c - 1], [r, c + 1], [r - 1, c], [r - 1, c + 1], [r + 1, c], [r + 1, c + 1]];
      return [[r, c - 1], [r, c + 1], [r - 1, c - 1], [r - 1, c], [r + 1, c - 1], [r + 1, c]];
    }

    function makeGrid(fill) {
      var g = [];
      for (var r = 0; r < ROWS; r++) {
        var row = [];
        for (var c = 0; c < COLS; c++) row.push(fill);
        g.push(row);
      }
      return g;
    }

    function fillStartRows() {
      for (var r = 0; r < CONFIG.startRows; r++) {
        var n = rowCols(r);
        for (var c = 0; c < n; c++) {
          grid[r][c] = Rand.int(0, PAL.length - 1);
          sup[r][c] = Rand.chance(WALL_SUP);
        }
      }
      // Exactly ONE blight bubble to start, in a random non-super cell.
      var candidates = [];
      for (var br = 0; br < CONFIG.startRows; br++) {
        var bn = rowCols(br);
        for (var bc = 0; bc < bn; bc++) if (!sup[br][bc]) candidates.push([br, bc]);
      }
      if (candidates.length) {
        var pick = Rand.pick(candidates);
        blk[pick[0]][pick[1]] = true;
      }
    }

    function activeColors() {
      var seen = {}, list = [];
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          var v = grid[r][c];
          if (v !== null && !sup[r][c] && !seen[v]) { seen[v] = true; list.push(v); }
        }
      }
      return list;
    }
    function pickShootColor() {
      var a = activeColors();
      return a.length ? Rand.pick(a) : Rand.int(0, PAL.length - 1);
    }

    // --- collision / snapping ---------------------------------------------
    function collideAt(x, y) {
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (grid[r][c] === null) continue;
          var dx = x - cellX(r, c), dy = y - cellY(r);
          if (dx * dx + dy * dy <= COLLIDE * COLLIDE) return true;
        }
      }
      return false;
    }

    // Nearest empty cell to (x,y): snap to the rounded cell, or breadth-first
    // out from it when that one is taken.
    function snapCell(x, y) {
      var r = clamp(Math.round((y - GRID_TOP - R) / ROWH), 0, ROWS - 1);
      var c = clamp(Math.round((x - R - (isOffset(r) ? R : 0)) / (2 * R)), 0, rowCols(r) - 1);
      if (grid[r][c] === null) return { r: r, c: c };
      var seen = {}, q = [{ r: r, c: c }];
      seen[key(r, c)] = true;
      while (q.length) {
        var cur = q.shift();
        if (validCell(cur.r, cur.c) && grid[cur.r][cur.c] === null) return cur;
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc)) continue;
          var k = key(nr, nc);
          if (seen[k]) continue;
          seen[k] = true; q.push({ r: nr, c: nc });
        }
      }
      return null;
    }

    // Same-colour connected group. SUPER and blighted bubbles never take part
    // in a colour match — they only leave the board another way.
    function floodGroup(sr, sc) {
      if (sup[sr][sc] || blk[sr][sc]) return [];
      var color = grid[sr][sc];
      var seen = {}, q = [{ r: sr, c: sc }], group = [];
      seen[key(sr, sc)] = true;
      while (q.length) {
        var cur = q.shift();
        group.push(cur);
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc) || grid[nr][nc] === null || sup[nr][nc] || blk[nr][nc]) continue;
          if (grid[nr][nc] !== color) continue;
          var k = key(nr, nc);
          if (seen[k]) continue;
          seen[k] = true; q.push({ r: nr, c: nc });
        }
      }
      return group;
    }

    // Everything no longer connected to the ceiling falls.
    function dropFloating() {
      var anchored = {}, q = [];
      for (var c = 0; c < rowCols(0); c++) {
        if (grid[0][c] !== null) { anchored[key(0, c)] = true; q.push({ r: 0, c: c }); }
      }
      while (q.length) {
        var cur = q.shift();
        var nb = neighbors(cur.r, cur.c);
        for (var i = 0; i < nb.length; i++) {
          var nr = nb[i][0], nc = nb[i][1];
          if (!validCell(nr, nc) || grid[nr][nc] === null) continue;
          var k = key(nr, nc);
          if (anchored[k]) continue;
          anchored[k] = true; q.push({ r: nr, c: nc });
        }
      }
      var dropped = [];
      for (var r = 0; r < ROWS; r++) {
        for (var cc = 0; cc < rowCols(r); cc++) {
          if (grid[r][cc] === null || anchored[key(r, cc)]) continue;
          dropped.push({ x: cellX(r, cc), y: cellY(r), color: grid[r][cc], sup: sup[r][cc], blk: blk[r][cc] });
          grid[r][cc] = null; sup[r][cc] = false; blk[r][cc] = false;
        }
      }
      return dropped;
    }

    // --- effects (all through the engine Fx layer) -------------------------
    function popFx(x, y, idx, isSuper) {
      var base = (idx != null && PAL[idx]) ? PAL[idx] : PAL[0];
      Fx.burst(x, y, { color: isSuper ? [PAL[0].core, PAL[1].core, PAL[2].core] : base.core,
        count: 6, speed: 260, size: 5, life: 0.5, grav: 900 });
      Fx.burst(x, y, { color: isSuper ? "#ffffff" : base.light, count: 3, speed: 340, size: 2.5, life: 0.3 });
      Fx.ring(x, y, { from: R * 0.6, to: R * 2.4, color: isSuper ? "#ffffff" : base.core, width: 4, life: 0.35 });
    }

    // --- launcher / ball ---------------------------------------------------
    function newBall(colorIndex, isSuper) {
      return { x: LX, y: LY, vx: 0, vy: 0, color: colorIndex, sup: !!isSuper, r: R, flying: false };
    }
    function updateAimFromPoint(p) {
      var dx = p.x - LX, dy = p.y - LY;
      if (dy > -1) dy = -1;                          // keep the aim upward
      aimAngle = clamp(Math.atan2(dx, -dy), -MAX_AIM, MAX_AIM);
    }
    function fire() {
      if (ball.flying || ended) return;
      ball.vx = Math.sin(aimAngle) * SPEED;
      ball.vy = -Math.cos(aimAngle) * SPEED;
      ball.flying = true;
      trail = [];
      shotCount++;
      launchPunch = 1;
      Sound.clip("shoot", 0.5, ball.sup ? 1.16 : 1);   // a super leaves the tube brighter
    }

    // Contaminate exactly ONE random neighbour of any blighted bubble.
    function spreadBlight() {
      var targets = [], seen = {};
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (!blk[r][c] || grid[r][c] === null) continue;
          var nb = neighbors(r, c);
          for (var i = 0; i < nb.length; i++) {
            var nr = nb[i][0], nc = nb[i][1];
            if (!validCell(nr, nc)) continue;
            if (grid[nr][nc] === null || blk[nr][nc] || sup[nr][nc]) continue;
            var bk = key(nr, nc);
            if (!seen[bk]) { seen[bk] = true; targets.push([nr, nc]); }
          }
        }
      }
      if (!targets.length) return;
      var pick = Rand.pick(targets);
      blk[pick[0]][pick[1]] = true;
      Fx.ring(cellX(pick[0], pick[1]), cellY(pick[0]),
        { from: R * 0.2, to: R * 2.2, color: "rgba(130,0,255,0.85)", width: 4, life: 0.45 });
      // A 70 ms tick pitched down to 0.7: quiet in energy but short, so it needs
      // a high gain to sit next to pop/drop without ever masking them.
      Sound.clip("spread", 0.85, 0.7);
    }

    // Simulate the shot for the dotted aim preview (mirrors real flight).
    function simulateShot(angle) {
      var stepLen = R * 0.6;
      var x = LX, y = LY, dx = Math.sin(angle) * stepLen, dy = -Math.cos(angle) * stepLen;
      var pts = [{ x: x, y: y }];
      for (var i = 0; i < 360; i++) {
        x += dx; y += dy;
        if (x - R < 0) { x = R; dx = -dx; }
        else if (x + R > view.w) { x = view.w - R; dx = -dx; }
        if (y - R <= GRID_TOP || collideAt(x, y)) return pts;
        pts.push({ x: x, y: y });
      }
      return pts;
    }

    function comboTier(n) { return n >= 12 ? 3 : n >= 8 ? 2 : n >= 5 ? 1 : 0; }
    // Tier 0 is a plain 3-match: frequent, so it gets the score pop and nothing
    // else. The three tiers above it graduate to a hero callout.
    var TIER_WORD = ["", "GREAT!", "AWESOME!", "UNREAL!"];
    var TIER_POP  = ["", "streak", "combo", "ultra"];
    // Tints for the score pop, defined in the SKIN block: blue -> gold -> pink
    // -> blight violet, so the colour alone says how big the clear was.
    var POP_TIER  = ["pop-t0", "pop-t1", "pop-t2", "pop-t3"];

    // Add every super on the board (plus its neighbours) to a clear set —
    // one detonation takes them all.
    function collectSuperBlast(add) {
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (!sup[r][c] || grid[r][c] === null) continue;
          add(r, c);
          var nb = neighbors(r, c);
          for (var i = 0; i < nb.length; i++) add(nb[i][0], nb[i][1]);
        }
      }
    }
    function touchesSuper(cell) {
      var nb = neighbors(cell.r, cell.c);
      for (var i = 0; i < nb.length; i++) {
        var r = nb[i][0], c = nb[i][1];
        if (validCell(r, c) && grid[r][c] !== null && sup[r][c]) return true;
      }
      return false;
    }

    // Resolve the shot after the ball has snapped into `cell`.
    function resolveShot(cell) {
      var mark = {}, list = [];
      function add(r, c) {
        if (validCell(r, c) && grid[r][c] !== null) {
          var k = key(r, c);
          if (!mark[k]) { mark[k] = true; list.push({ r: r, c: c }); }
        }
      }

      // 1) Colour match — only when the placed bubble is a normal colour.
      if (!sup[cell.r][cell.c]) {
        var group = floodGroup(cell.r, cell.c);
        if (group.length >= 3) for (var i = 0; i < group.length; i++) add(group[i].r, group[i].c);
      }
      // 2) Direct super hit -> detonate ALL supers (+ their neighbours).
      var hadSuper = touchesSuper(cell);
      if (hadSuper) collectSuperBlast(add);

      if (list.length === 0) {
        // Nothing cleared: the bubble just sticks and the streak resets.
        streak = 0;
        Sound.clip("stick", 0.35, 1.1);                // a dry thud: nothing cleared
        Fx.shake(2, 0.1);
        return;
      }

      var cx = 0, cy = 0, color = grid[cell.r][cell.c];
      for (var k = 0; k < list.length; k++) {
        var g = list[k];
        popFx(cellX(g.r, g.c), cellY(g.r), grid[g.r][g.c], sup[g.r][g.c]);
        cx += cellX(g.r, g.c); cy += cellY(g.r);
        grid[g.r][g.c] = null; sup[g.r][g.c] = false; blk[g.r][g.c] = false;
      }
      var cleared = list.length;
      cx /= list.length; cy /= list.length;

      // Cascade: everything cut off from the ceiling falls (and scores).
      var dropped = dropFloating();
      for (var d = 0; d < dropped.length; d++) {
        fallers.push({ x: dropped[d].x, y: dropped[d].y, vx: Rand.range(-70, 70), vy: Rand.range(-40, 40),
          color: dropped[d].color, sup: dropped[d].sup, blk: dropped[d].blk, r: R, life: 1.3 });
      }
      if (dropped.length >= 5) fireworks(dropped);
      cleared += dropped.length;
      totalCleared += cleared;
      HUD.setLeft(totalCleared, "POPPED");

      // --- scoring ---
      streak++;
      var mult = Math.min(streak, 6);
      var gained = cleared * 12 * mult + (hadSuper ? 150 : 0);
      score += gained;
      if (cleared > maxCombo) maxCombo = cleared;
      HUD.setScore(score);
      HUD.punch(hadSuper ? "#ffffff" : PAL[color] ? PAL[color].core : null);

      // --- impact ---
      // Fx keeps what is positional (burst, ring, freeze); the shake and the
      // full-screen flash of the big beats belong to the Pop style fired just
      // below, so they are not doubled here.
      var mc = PAL[color] || PAL[0];
      var tier = comboTier(cleared);
      if (hadSuper) {
        Fx.shake(12, 0.4); Fx.freeze(0.06);
        Fx.burst(cx, cy, { color: "#ffffff", count: 12, speed: 420, size: 3, life: 0.5 });
        Fx.ring(cx, cy, { from: R, to: R * 5, color: "#ffffff", width: 6, life: 0.5 });
      } else {
        Fx.shake(Math.min(4 + cleared * 1.3, 26), 0.32);
        if (tier >= 2) {
          Fx.freeze(0.05);
          if (tier === 2) Fx.flash(mc.glow, 0.22);       // tier 3 rides `ultra`'s own flash
          Fx.burst(cx, cy, { color: mc.light, count: 12, speed: 420, size: 3, life: 0.5 });
          Fx.ring(cx, cy, { from: R, to: R * 5, color: mc.light, width: 6, life: 0.5 });
        } else if (tier >= 1) { Fx.flash(mc.glow, 0.15); }
      }

      // --- callouts ---
      // The gain always pops on the cluster it came from, tinted by the tier.
      // `cy` can sit right under the ceiling, so hold the pop clear of the HUD.
      var popTier = hadSuper ? 3 : tier;
      Pop.show("score", { word: "+" + gained, cls: POP_TIER[popTier], hold: 160,
                          at: { x: cx, y: Math.max(cy - R - 34, Layout.top + 100) } });
      // The hero line above it only fires once the clear is worth shouting
      // about; a lone streak with a small clear keeps the corner sticker.
      var streakSub = mult > 1 ? "x" + mult + " STREAK" : cleared + " POPPED";
      if (hadSuper) {
        Pop.show("combo", { word: "SUPER BLAST", sub: streakSub, hold: 420,
                            cls: "pop-blast" });
      } else if (tier >= 1) {
        Pop.show(TIER_POP[tier], { word: TIER_WORD[tier], sub: streakSub,
                                   hold: tier >= 3 ? 420 : 300 });
      } else if (mult > 1) {
        Pop.show("streak", { word: "x" + mult + " STREAK", at: "topRight", hold: 260 });
      }

      // --- audio ---
      Sound.clip("pop", 0.55, 1 + Math.min(cleared, 14) * 0.045);   // climbs with the cluster
      if (hadSuper) Sound.clip("blast", 0.65);
      if (dropped.length) Sound.clip("drop", 0.45, 1 + Math.min(dropped.length, 12) * 0.02);
    }

    // Fireworks when 5+ bubbles fall at once.
    function fireworks(drops) {
      var pts = drops.slice(0, Math.min(drops.length, 4));
      for (var p = 0; p < pts.length; p++) {
        var fw = pts[p], col = PAL[fw.color] || PAL[p % PAL.length];
        Fx.burst(fw.x, fw.y, { color: [col.core, col.light, "#ffffff"], count: 14, speed: 520, size: 5, life: 0.7, grav: 560 });
        Fx.ring(fw.x, fw.y, { from: R * 0.4, to: R * 5, color: col.glow, width: 5, life: 0.55 });
      }
      Fx.flash(PAL[Rand.int(0, PAL.length - 1)].glow, 0.2);
      // Off in a corner: the cluster already owns the centre this frame.
      Pop.show("bonus", { word: "CASCADE", sub: "+" + drops.length + " FELL",
                          at: "lowerLeft", hold: 320 });
      Sound.clip("cheer", 0.5, Rand.range(0.97, 1.05));
    }

    // Push a fresh row in from the top — the pressure that ends the round.
    function pushRow() {
      var bottom = grid[ROWS - 1];
      for (var c0 = 0; c0 < COLS; c0++) if (bottom[c0] !== null) return;  // overflow: danger check handles it
      grid.pop(); sup.pop(); blk.pop(); wobble.pop();
      rowShift++;
      var row = [], srow = [], brow = [], wrow = [];
      for (var c = 0; c < COLS; c++) { row.push(null); srow.push(false); brow.push(false); wrow.push(0); }
      var n = rowCols(0);
      for (var cc = 0; cc < n; cc++) { row[cc] = Rand.int(0, PAL.length - 1); srow[cc] = Rand.chance(WALL_SUP); }
      grid.unshift(row); sup.unshift(srow); blk.unshift(brow); wobble.unshift(wrow);
      fieldY = -ROWH;
      Fx.shake(6, 0.25);
      Sound.clip("press", 0.5, 0.85);                  // the wall grinding one row closer
    }

    function lowestBubbleBottom() {
      for (var r = ROWS - 1; r >= 0; r--)
        for (var c = 0; c < rowCols(r); c++)
          if (grid[r][c] !== null) return cellY(r) + R;
      return 0;
    }

    // --- lifecycle ---------------------------------------------------------
    function reset() {
      geometry();
      ROWS = Math.max(10, Math.ceil((Layout.bottom - Layout.top) / ROWH) + 2);
      buildSprites();
      bgCanvas = null; buildBackground();
      grid = makeGrid(null); sup = makeGrid(false); blk = makeGrid(false); wobble = makeGrid(0);
      rowShift = 0;
      fillStartRows();
      score = 0;
      aimAngle = 0; aiming = false;
      shotCount = 0; maxCombo = 0; streak = 0;
      ended = false; blackTimer = 0; totalCleared = 0;
      fallers = []; trail = [];
      bgT = 0; fieldY = 0; launchPunch = 0;
      ball = newBall(pickShootColor(), Rand.chance(SHOT_SUP));
      nextColor = pickShootColor(); nextSuper = Rand.chance(SHOT_SUP);
      HUD.setScoreNow(0);
      HUD.setLeft(0, "POPPED");
    }

    function onDown(p) { if (ended || ball.flying) return; aiming = true; updateAimFromPoint(p); }
    function onMove(p) { if (ended || ball.flying || !aiming) return; updateAimFromPoint(p); }
    function onUp(p) {
      if (ended || ball.flying || !aiming) { aiming = false; return; }
      updateAimFromPoint(p); aiming = false; fire();
    }

    function update(dt) {
      bgT += dt;
      if (launchPunch > 0) launchPunch -= dt * 5;
      // The freshly pushed row slides down into place.
      if (fieldY < 0) fieldY = Math.min(0, fieldY + Math.abs(fieldY) * Math.min(1, dt * 16) + dt * 20);
      if (ended) { updateFallers(dt); return; }

      // Per-bubble wobble decay.
      for (var wr = 0; wr < ROWS; wr++)
        for (var wc = 0; wc < rowCols(wr); wc++)
          if (wobble[wr][wc] > 0) wobble[wr][wc] = Math.max(0, wobble[wr][wc] - dt * 3.5);

      // Blight spreads on a fixed cadence — never exponential.
      blackTimer += dt;
      if (blackTimer >= CONFIG.blightInterval) { blackTimer = 0; spreadBlight(); }

      if (ball.flying) {
        var remaining = dt, maxStep = R / SPEED;   // sub-steps so nothing is missed
        while (ball.flying && remaining > 0) {
          var step = Math.min(remaining, maxStep);
          ball.x += ball.vx * step; ball.y += ball.vy * step;
          remaining -= step;
          if (ball.x - R < 0) {
            ball.x = R; ball.vx = -ball.vx;
            Fx.ring(ball.x, ball.y, { from: R * 0.3, to: R * 1.8, color: "rgba(255,255,255,0.55)", width: 2.5, life: 0.22 });
            Sound.clip("stick", 0.22, 1.5);            // the same thud, glancing off the wall
          } else if (ball.x + R > view.w) {
            ball.x = view.w - R; ball.vx = -ball.vx;
            Fx.ring(ball.x, ball.y, { from: R * 0.3, to: R * 1.8, color: "rgba(255,255,255,0.55)", width: 2.5, life: 0.22 });
            Sound.clip("stick", 0.22, 1.5);
          }
          if (ball.y - R <= GRID_TOP || collideAt(ball.x, ball.y)) { landBall(); break; }
        }
        trail.push({ x: ball.x, y: ball.y });
        if (trail.length > 8) trail.shift();
      }

      // Danger: pulse the overlay glow once the stack creeps down.
      var near = clamp((lowestBubbleBottom() - (DANGER_Y - 200)) / 200, 0, 1);
      Overlay.vignette("#ff4d6d", near * 0.9);

      updateFallers(dt);
    }

    function landBall() {
      var cell = snapCell(ball.x, ball.y);
      if (!cell) { endRun("OVERRUN!"); return; }
      // Landing impact: ripple + wobble on the neighbours.
      var lx = cellX(cell.r, cell.c), ly = cellY(cell.r);
      var ballCol = ball.sup ? PAL[0] : (PAL[ball.color] || PAL[0]);
      Fx.ring(lx, ly, { from: R * 0.35, to: R * 2.4, width: 3, life: 0.28,
        color: ball.sup ? "rgba(255,255,255,0.7)" : ballCol.glow });
      wobble[cell.r][cell.c] = 1.0;
      var nb = neighbors(cell.r, cell.c);
      for (var i = 0; i < nb.length; i++) {
        var nr = nb[i][0], nc = nb[i][1];
        if (validCell(nr, nc) && grid[nr][nc] !== null) wobble[nr][nc] = Math.max(wobble[nr][nc], 0.6);
      }
      grid[cell.r][cell.c] = ball.color;
      sup[cell.r][cell.c] = ball.sup;
      ball.flying = false; trail = [];

      resolveShot(cell);

      if (shotCount > 0 && shotCount % ADD_SHOTS === 0) pushRow();
      if (lowestBubbleBottom() >= DANGER_Y) { endRun("OVERRUN!"); return; }

      ball = newBall(nextColor, nextSuper);
      nextColor = pickShootColor(); nextSuper = Rand.chance(SHOT_SUP);
    }

    function updateFallers(dt) {
      for (var i = fallers.length - 1; i >= 0; i--) {
        var f = fallers[i];
        f.x += f.vx * dt; f.y += f.vy * dt; f.vy += 1600 * dt; f.life -= dt;
        if (f.y - f.r > view.h || f.life <= 0) fallers.splice(i, 1);
      }
    }

    /* ---------------- sprite / background caching ---------------- */
    function makeCanvas(w, h) {
      var cv = document.createElement("canvas");
      cv.width = w; cv.height = h;
      return cv;
    }
    // A glossy bubble, rendered ONCE (gradients + glow baked in), then blitted.
    function makeBubbleSprite(pal) {
      var pad = 10, size = (R + pad) * 2, cv = makeCanvas(size, size), c = cv.getContext("2d");
      var x = size / 2, y = size / 2;
      c.shadowColor = pal.glow; c.shadowBlur = 10;
      var g = c.createRadialGradient(x - R * 0.35, y - R * 0.4, R * 0.15, x, y, R);
      g.addColorStop(0, pal.light); g.addColorStop(0.55, pal.core); g.addColorStop(1, pal.edge);
      c.fillStyle = g; c.beginPath(); c.arc(x, y, R, 0, PI2); c.fill();
      c.shadowBlur = 0;
      var hx = x - R * 0.3, hy = y - R * 0.34;
      var hg = c.createRadialGradient(hx, hy, 0, hx, hy, R * 0.55);
      hg.addColorStop(0, "rgba(255,255,255,0.85)"); hg.addColorStop(1, "rgba(255,255,255,0)");
      c.fillStyle = hg; c.beginPath(); c.arc(hx, hy, R * 0.4, 0, PI2); c.fill();
      return cv;
    }
    // The rainbow SUPER bubble: colour wedges + white rim + gloss.
    function makeSuperSprite() {
      var pad = 10, size = (R + pad) * 2, cv = makeCanvas(size, size), c = cv.getContext("2d");
      var x = size / 2, y = size / 2, n = PAL.length;
      c.shadowColor = "rgba(255,255,255,0.9)"; c.shadowBlur = 12;
      c.fillStyle = "#fff"; c.beginPath(); c.arc(x, y, R, 0, PI2); c.fill();
      c.shadowBlur = 0;
      for (var i = 0; i < n; i++) {
        var a0 = -Math.PI / 2 + i * PI2 / n, a1 = a0 + PI2 / n;
        c.beginPath(); c.moveTo(x, y); c.arc(x, y, R, a0, a1); c.closePath();
        var g = c.createRadialGradient(x, y, R * 0.2, x, y, R);
        g.addColorStop(0, PAL[i].light); g.addColorStop(1, PAL[i].core);
        c.fillStyle = g; c.fill();
      }
      c.lineWidth = R * 0.12; c.strokeStyle = "rgba(255,255,255,0.9)";
      c.beginPath(); c.arc(x, y, R * 0.88, 0, PI2); c.stroke();
      var hx = x - R * 0.3, hy = y - R * 0.34;
      var hg = c.createRadialGradient(hx, hy, 0, hx, hy, R * 0.5);
      hg.addColorStop(0, "rgba(255,255,255,0.85)"); hg.addColorStop(1, "rgba(255,255,255,0)");
      c.fillStyle = hg; c.beginPath(); c.arc(hx, hy, R * 0.36, 0, PI2); c.fill();
      return cv;
    }
    // A dark gas-cloud blighted bubble — irregular overlapping blobs.
    function makeBlackSprite() {
      var pad = 14, size = (R + pad) * 2, cv = makeCanvas(size, size), c = cv.getContext("2d");
      var x = size / 2, y = size / 2;
      var aura = c.createRadialGradient(x, y, R * 0.4, x, y, R + 10);
      aura.addColorStop(0, "rgba(80,0,160,0.5)"); aura.addColorStop(1, "rgba(10,0,30,0)");
      c.fillStyle = aura; c.beginPath(); c.arc(x, y, R + 10, 0, PI2); c.fill();
      var blobs = [[0,0,1.0], [R*-0.18,R*-0.12,0.90], [R*0.15,R*0.09,0.86], [R*-0.10,R*0.17,0.83], [R*0.13,R*-0.17,0.85]];
      for (var i = 0; i < blobs.length; i++) {
        var ox = blobs[i][0], oy = blobs[i][1], rs = blobs[i][2];
        var g = c.createRadialGradient(x + ox - R * 0.15, y + oy - R * 0.18, R * 0.08, x + ox, y + oy, R * rs);
        g.addColorStop(0, "rgba(65,0,105,0.92)");
        g.addColorStop(0.5, "rgba(18,0,32,0.96)");
        g.addColorStop(1, "rgba(4,0,8,0)");
        c.fillStyle = g; c.beginPath(); c.arc(x + ox, y + oy, R * rs, 0, PI2); c.fill();
      }
      c.shadowColor = "rgba(150,0,255,0.65)"; c.shadowBlur = 10;
      c.strokeStyle = "rgba(120,0,220,0.45)"; c.lineWidth = 2;
      c.beginPath(); c.arc(x, y, R * 0.87, 0, PI2); c.stroke();
      c.shadowBlur = 0;
      var core = c.createRadialGradient(x, y, 0, x, y, R * 0.52);
      core.addColorStop(0, "rgba(170,50,255,0.22)"); core.addColorStop(1, "rgba(170,50,255,0)");
      c.fillStyle = core; c.beginPath(); c.arc(x, y, R * 0.52, 0, PI2); c.fill();
      return cv;
    }
    function buildSprites() {
      if (bubbleSprites) return;
      bubbleSprites = [];
      for (var i = 0; i < PAL.length; i++) bubbleSprites.push(makeBubbleSprite(PAL[i]));
      superSprite = makeSuperSprite();
      blackSprite = makeBlackSprite();
    }
    function buildBackground() {
      if (bgCanvas) return;
      bgCanvas = makeCanvas(view.w, view.h);
      var c = bgCanvas.getContext("2d");
      var img = Images.bg;
      if (img && img.width) {
        // Cover-fit the embedded artwork to the design canvas (crop, no stretch).
        var s = Math.max(view.w / img.width, view.h / img.height);
        var dw = img.width * s, dh = img.height * s;
        c.drawImage(img, (view.w - dw) / 2, (view.h - dh) / 2, dw, dh);
      } else {
        var g = c.createLinearGradient(0, 0, 0, view.h);
        g.addColorStop(0, "#231a4a"); g.addColorStop(1, "#0b0820");
        c.fillStyle = g; c.fillRect(0, 0, view.w, view.h);
      }
      // Darken behind the HUD so the score always reads clearly.
      var band = Layout.top + 60;
      var tg = c.createLinearGradient(0, 0, 0, band);
      tg.addColorStop(0, "rgba(0,0,0,0.55)"); tg.addColorStop(1, "rgba(0,0,0,0)");
      c.fillStyle = tg; c.fillRect(0, 0, view.w, band);
      // Gentle vignette to focus the play area.
      var vg = c.createRadialGradient(view.w / 2, view.h * 0.5, view.h * 0.34, view.w / 2, view.h * 0.5, view.h * 0.82);
      vg.addColorStop(0, "rgba(0,0,0,0)"); vg.addColorStop(1, "rgba(0,0,0,0.42)");
      c.fillStyle = vg; c.fillRect(0, 0, view.w, view.h);
    }

    /* ---------------- rendering (blit-based, cheap) ---------------- */
    function drawSprite(x, y, r, idx, isSuper, isBlack, alpha, rot) {
      var spr = isBlack ? blackSprite : (isSuper ? superSprite : bubbleSprites[idx]);
      if (!spr) return;
      var s = r / R, w = spr.width * s, half = w / 2;
      ctx.save();
      if (alpha != null && alpha < 1) ctx.globalAlpha = alpha;
      if (isSuper && !isBlack && rot) {
        ctx.translate(x, y); ctx.rotate(rot);
        ctx.drawImage(spr, -half, -half, w, w);
      } else {
        ctx.drawImage(spr, x - half, y - half, w, w);
      }
      ctx.restore();
    }

    function render() {
      ctx.drawImage(bgCanvas, 0, 0, view.w, view.h);
      drawDangerLine();

      // Grid bubbles (with the push-down slide offset and per-bubble wobble).
      ctx.save();
      ctx.translate(0, fieldY);
      var superRot = bgT * 0.6;
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (grid[r][c] === null) continue;
          var wob = wobble[r][c];
          if (wob > 0.01) {
            var ws = 1 + wob * 0.13 * Math.sin(bgT * 32);
            var gx = cellX(r, c), gy = cellY(r);
            ctx.save();
            ctx.translate(gx, gy); ctx.scale(ws, ws); ctx.translate(-gx, -gy);
            drawSprite(gx, gy, R, grid[r][c], sup[r][c], blk[r][c], 1, sup[r][c] ? superRot : 0);
            ctx.restore();
          } else {
            drawSprite(cellX(r, c), cellY(r), R, grid[r][c], sup[r][c], blk[r][c], 1, sup[r][c] ? superRot : 0);
          }
        }
      }
      ctx.restore();

      drawBlightSmoke();

      for (var fi = 0; fi < fallers.length; fi++) {
        var f = fallers[fi];
        drawSprite(f.x, f.y, f.r, f.color, f.sup, f.blk, clamp(f.life, 0, 1), 0);
      }

      if (!ball.flying && !ended) drawAim();
      drawLauncher();
      if (ball.flying) drawTrail();
      if (!ended) drawSprite(ball.x, ball.y, R, ball.color, ball.sup, false, 1, ball.sup ? bgT * 0.6 : 0);
      drawNextPreview();
    }

    // Animated smoke aura around blighted bubbles (drawn live: it is cheap).
    function drawBlightSmoke() {
      ctx.save();
      ctx.translate(0, fieldY);
      for (var r = 0; r < ROWS; r++) {
        for (var c = 0; c < rowCols(r); c++) {
          if (!blk[r][c] || grid[r][c] === null) continue;
          var bx = cellX(r, c), by = cellY(r), phase = r * 2.3 + c * 5.7;
          var auraR = R * (1.06 + 0.09 * Math.sin(bgT * 2.4 + phase));
          ctx.globalAlpha = 0.18 + 0.07 * Math.sin(bgT * 2.1 + phase);
          ctx.fillStyle = "#4a0090";
          ctx.beginPath(); ctx.arc(bx, by, auraR, 0, PI2); ctx.fill();
          for (var w = 0; w < 3; w++) {
            var a = (w / 3) * PI2 + bgT * (0.9 + w * 0.22) + phase;
            var dist = R * (0.6 + 0.14 * Math.sin(bgT * 1.7 + w * 1.3));
            var wr = R * (0.19 + 0.08 * Math.sin(bgT * 2.5 + w));
            ctx.globalAlpha = 0.28 + 0.1 * Math.sin(bgT * 1.9 + w * 0.8);
            ctx.fillStyle = w === 0 ? "#8800ff" : (w === 1 ? "#3d0070" : "#c050ff");
            ctx.beginPath(); ctx.arc(bx + Math.cos(a) * dist, by + Math.sin(a) * dist * 0.82, wr, 0, PI2); ctx.fill();
          }
        }
      }
      ctx.globalAlpha = 1;
      ctx.restore();
    }

    function drawTrail() {
      var col = PAL[ball.color] || PAL[0];
      for (var i = 0; i < trail.length; i++) {
        ctx.globalAlpha = (i / trail.length) * 0.3;
        ctx.fillStyle = ball.sup ? "#ffffff" : col.core;
        ctx.beginPath(); ctx.arc(trail[i].x, trail[i].y, R * (0.35 + 0.5 * (i / trail.length)), 0, PI2); ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    // Dotted trajectory only — no ghost bubble at the landing spot.
    function drawAim() {
      var pts = simulateShot(aimAngle);
      ctx.fillStyle = "#ffffff";
      for (var i = 0; i < pts.length; i += 3) {
        ctx.globalAlpha = 0.5 * (1 - i / pts.length);
        ctx.beginPath(); ctx.arc(pts[i].x, pts[i].y, 4, 0, PI2); ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    function drawLauncher() {
      var punch = launchPunch > 0 ? launchPunch : 0;
      ctx.strokeStyle = "rgba(255,255,255,0.25)";
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(LX, LY, (R + 16) * (1 - punch * 0.12), 0, PI2); ctx.stroke();
    }

    function drawNextPreview() {
      var nx = LX + 118, ny = LY, nr = R * 0.6;
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.font = "bold 15px -apple-system,Segoe UI,Roboto,sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("NEXT", nx, ny - nr - 12);
      ctx.textAlign = "left";
      drawSprite(nx, ny, nr, nextColor, nextSuper, false, 1, 0);
    }

    function drawDangerLine() {
      var closeness = clamp((lowestBubbleBottom() - (DANGER_Y - 260)) / 260, 0, 1);
      if (closeness <= 0.02) return;
      var pulse = 0.35 + 0.35 * Math.abs(Math.sin(bgT * 4));
      ctx.save();
      ctx.globalAlpha = closeness * pulse;
      ctx.strokeStyle = "#ff4d6d";
      ctx.lineWidth = 3;
      ctx.setLineDash([14, 10]);
      ctx.beginPath(); ctx.moveTo(0, DANGER_Y); ctx.lineTo(view.w, DANGER_Y); ctx.stroke();
      ctx.restore();
    }

    function onTimeUp() { endRun(CONFIG.copy.timeUp); }

    function endRun(title) {
      if (ended) return;
      ended = true;
      var best = Math.max(score, Store.get("bestScore", 0));
      var stars = score >= 3000 ? 3 : score >= 2000 ? 2 : score > 0 ? 1 : 0;
      endRound({
        title: title,
        variant: stars === 3 ? "win" : "",
        score: score,
        stars: stars,
        rows: [
          { label: "BUBBLES CLEARED", value: totalCleared },
          { label: "MAX CHAIN",       value: maxCombo, grade: "accent" },
          { label: "BEST SCORE",      value: best,     grade: "gold" }
        ],
        track: { score: score, reason: title, maxCombo: maxCombo, cleared: totalCleared }
      });
    }

    return { reset: reset, onDown: onDown, onMove: onMove, onUp: onUp,
             update: update, render: render, onTimeUp: onTimeUp, onResize: onResize };
  })();

